'use strict';
/* La Cueva de Garra Negra, Nivel 2: Las Grutas (12/11, pedido del dueño: "que sean al menos 3 niveles… que pasen cosas en
   los niveles como trampas"; "recordá armonizar la paleta de colores según la región").
   Mapa nuevo del Taller (cueva_grutas, 1436×802, piezas ed_gru_*), de las tres capas de Nano Banana Pro del dueño. La capa
   magenta vino con cosas de más y sin paredes: los objetos salieron de lo que difiere la completa del suelo vacío y lo
   caminable se midió a mano (trabajo\nuevos_flow\cueva_nivel2\preparar.py). Paleta llevada al tono del Nivel 1 (paleta_cueva.py).
   - Se baja por el SUMIDERO del Nivel 1 (T al lado) y se llega por el túnel de la sala de la derecha; el túnel vuelve arriba.
   - En la sala de la izquierda, el POZO de raíces (T) baja al Nivel 3 (La Fosa, ck_cueva_fosa.js).
   - Luz: sólo la de los hongos (verde) y los cristales (violeta y azul), que laten despacio. Oscura (ck_oscuridad.js).
   - Trampas: dos cepos en el pasillo que baja de la sala de los huesos y una fosa tapada en el pasillo largo
     (ck_trampas_suelo.js); en la sala de las telarañas se camina más lento.
   - Dos cofres del juego (T) donde estaban los pintados: en la sala de los cristales y en la de las telarañas.
   Va DESPUÉS de ck_cueva_galerias.js (le saca el cartel del sumidero). Borrar su línea: el sumidero vuelve a ser cartel. */
window.CK_GRUTAS_MINI = 'data:image/png;base64,';
(function () {
  if (typeof MainGameScene === 'undefined' || typeof INTERIOR_LAYOUTS === 'undefined') return;
  const D = window.EDITOR_DATA, ID = 'cueva_grutas', GALERIAS = 'cueva_galerias', FOSA = 'cueva_fosa';
  if (!D || !D.mapas || !D.mapas[ID] || !INTERIOR_LAYOUTS['ed_' + ID]) return;
  const Z = 'ed_' + ID + '.main', Z1 = 'ed_' + GALERIAS + '.main', Z3 = 'ed_' + FOSA + '.main';
  const P = MainGameScene.prototype;
  const G1 = window.CK_GALERIAS;
  const SUMIDERO = (G1 && G1.LUGAR && G1.LUGAR.sumidero) || { x: 217, y: 214 };
  const LUGAR = { tunel: { x: 1258, y: 250, w: 70, h: 12 }, pozo: { x: 196, y: 356 }, cristales: { x: 560, y: 200 }, huesos: { x: 850, y: 400 }, telaranas: { x: 455, y: 660 } };
  const LLEGA = { grutas: { x: 1292, y: 292 }, galerias: { x: SUMIDERO.x, y: SUMIDERO.y + 26 } };
  const COFRES = [[625, 160], [458, 628]];
  const PENUMBRA = [26, 24, 36];
  const VERDE = [120, 255, 160], VIOLETA = [190, 120, 255], AZUL = [120, 170, 255];
  const LUCES = [
    { x: 93, y: 290, c: VERDE, r: 95, f: 0.95 }, { x: 297, y: 285, c: VERDE, r: 95, f: 0.95 }, { x: 361, y: 350, c: VERDE, r: 45, f: 0.6 },
    { x: 880, y: 300, c: VERDE, r: 110, f: 0.95 }, { x: 402, y: 565, c: VERDE, r: 95, f: 0.95 }, { x: 401, y: 680, c: VERDE, r: 90, f: 0.9 },
    { x: 448, y: 135, c: VIOLETA, r: 85, f: 0.9 }, { x: 540, y: 125, c: AZUL, r: 70, f: 0.8 }, { x: 690, y: 170, c: AZUL, r: 95, f: 0.9 },
    { x: 423, y: 205, c: AZUL, r: 70, f: 0.8 }, { x: 641, y: 340, c: VIOLETA, r: 80, f: 0.9 }, { x: 486, y: 342, c: VIOLETA, r: 60, f: 0.8 },
    { x: 84, y: 410, c: VIOLETA, r: 70, f: 0.85 }, { x: 304, y: 420, c: VIOLETA, r: 55, f: 0.7 }, { x: 524, y: 570, c: VIOLETA, r: 80, f: 0.9 },
    { x: 196, y: 352, c: [200, 230, 210], r: 70, f: 0.35 }                                                // el resplandor pálido del pozo
  ];
  const TRAMPAS = [{ tipo: 'cepo', x: 878, y: 528 }, { tipo: 'cepo', x: 868, y: 584 }, { tipo: 'fosa', x: 420, y: 398 }];
  const TELARANAS = [[362, 552, 556, 718]];
  window.CK_GRUTAS = { ID, Z, LUGAR, LLEGA, LUCES, TRAMPAS };

  const nota = t => { try { window.CK_SIN_CARTELES_API && CK_SIN_CARTELES_API.nota(t); } catch (e) {} };
  const son = (k, v, o) => { try { return typeof sfx !== 'undefined' && sfx.fx(k, v, o); } catch (e) { return false; } };
  const zona = S => (S && S.currentZoneKey && S.currentZoneKey()) || '';
  const pies = S => ({ x: S.player.body ? S.player.body.center.x : S.player.x, y: S.player.body ? S.player.body.bottom : S.player.y });
  const hayFosa = () => !!(window.CK_FOSA && D.mapas[FOSA]);
  const cofresFijos = S => {
    const s = S && S.story; if (!s) return;
    s.flags = s.flags || {};
    const pos = (s.flags.cofres_pos3 = s.flags.cofres_pos3 || {});
    if (!pos[Z]) pos[Z] = COFRES.map(c => c.slice());
  };

  // ------------------------------------------------------------------ el sumidero del Nivel 1 deja de ser cartel
  const LG = INTERIOR_LAYOUTS['ed_' + GALERIAS];
  if (LG) INTERIOR_LAYOUTS['ed_' + GALERIAS] = function (kit) {
    const r = LG.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) a.talkers = (a.talkers || []).filter(t => !(t.lines || []).some(l => /todavía no te animás a bajar/.test(l)));
    return r;
  };
  // los lugares con T: el sumidero (Nivel 1) y el pozo de raíces (acá)
  const cercaDe = S => {
    if (!S.player || !S.player.body || !S.currentInterior || !S.currentInterior.area) return null;
    const z = zona(S), a = S.currentInterior.area, p = pies(S);
    if (z === Z1 && Math.hypot(p.x - (a.x + SUMIDERO.x), p.y - (a.y + SUMIDERO.y + 12)) < 50) return 'sumidero';
    if (z === Z && Math.hypot(p.x - (a.x + LUGAR.pozo.x), (p.y - (a.y + LUGAR.pozo.y + 26)) * 1.3) < 56) return 'pozo';
    return null;
  };
  const i0 = P.interact;
  P.interact = function () {
    try {
      const q = !this._overlay && !this.dialogOpen && this._gameMode === 'campaign' && !this.isDead && cercaDe(this);
      if (q === 'sumidero') {
        son('ck_derrumbe', 0.4, { rate: 1.3 });
        cofresFijos(this);
        if (!this._doorTransition && this.ckEntrar) this.ckEntrar(ID, LLEGA.grutas);
        return;
      }
      if (q === 'pozo') {
        if (hayFosa()) { this.switchInteriorArea('gr_fosa'); return; }
        this.openDialog('', ['Un pozo hondo entre las raíces. De abajo sube un gruñido… todavía no te animás a bajar']);
        return;
      }
    } catch (e) { console.warn('[grutas]', e); }
    return i0.apply(this, arguments);
  };
  const cambiar0 = P.switchInteriorArea;
  P.switchInteriorArea = function (nombre) {
    if (nombre === 'gr_galerias' && this._gameMode === 'campaign') {
      if (!this._doorTransition && this.ckEntrar) this.ckEntrar(GALERIAS, LLEGA.galerias);
      return;
    }
    return cambiar0.apply(this, arguments);
  };
  let registrado = false;
  const registrar = () => {
    if (registrado) return; registrado = true;
    try { const C = window.CK_PANTALLA_CARGA; if (C && C.REGION) C.REGION.unshift([/^cueva_grutas$/, 'La Cueva de Garra Negra']); } catch (e) {}
  };

  // ------------------------------------------------------------------ el mapa
  const L0 = INTERIOR_LAYOUTS['ed_' + ID];
  INTERIOR_LAYOUTS['ed_' + ID] = function (kit) {
    const r = L0.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) {
      registrar();
      ['talkers', 'fx', 'colliders', 'exits'].forEach(k => (a[k] = a[k] || []));
      a.ambient = [['amb_cueva', 0.55]].concat((a.ambient || []).filter(s => s[0] !== 'amb_cueva').map(s => [s[0], s[1] * 0.4]));
      a.exits.push({ x: LUGAR.tunel.x, y: LUGAR.tunel.y, w: LUGAR.tunel.w, h: LUGAR.tunel.h, key: 'walk', to: 'gr_galerias', hint: '▲ Las Galerías' });
      a.colliders.push({ x: LUGAR.pozo.x - 30, y: LUGAR.pozo.y - 8, w: 60, h: 18 });         // el pozo no se pisa
      a.talkers.push({ x: LUGAR.cristales.x, y: LUGAR.cristales.y, r: 56, lines: ['Cristales que brillan solos, violetas y azules. Están tibios al tacto'] });
      a.talkers.push({ x: LUGAR.huesos.x, y: LUGAR.huesos.y, r: 56, lines: ['Montañas de calaveras y cercos rotos: acá la manada guarda lo que caza'] });
      a.talkers.push({ x: LUGAR.telaranas.x, y: LUGAR.telaranas.y, r: 60, lines: ['Telarañas gruesas como sogas. Los pies se pegan al piso'] });
      a.talkers.push({ x: 820, y: 680, r: 50, lines: ['Zarpazos en la roca y huesos partidos. Algo muy grande pasó por acá'] });
    }
    return r;
  };

  // ------------------------------------------------------------------ el pozo (dibujado), el cartel de T y las telarañas
  const pozo = S => {
    try { if (S._ckGrPozo) S._ckGrPozo.destroy(); } catch (e) {}
    S._ckGrPozo = null;
    if (zona(S) !== Z || !S.currentInterior) return;
    const a = S.currentInterior.area, x = a.x + LUGAR.pozo.x, y = a.y + LUGAR.pozo.y;
    // (13/11) el agujero de PixelLab (ck_cueva_grutas_arte.js): un pozo negro con el borde de roca partida y raíces; el centro
    // del agujero queda donde estaba el de antes. Si el arte no cargó, queda el dibujado
    if (S.textures.exists('ckgr_pozo')) { S._ckGrPozo = S.add.image(x, y + 2, 'ckgr_pozo').setOrigin(0.5, 0.56).setScale(0.9).setDepth(7); return; }
    const g = S.add.graphics().setDepth(7);
    g.fillStyle(0x2a2018, 1).fillEllipse(x, y, 66, 26);
    g.fillStyle(0x120c09, 1).fillEllipse(x, y + 1, 56, 20);
    g.fillStyle(0x050304, 1).fillEllipse(x, y + 2, 40, 13);
    g.lineStyle(2, 0x5a4230, 1);                                              // raíces que bajan
    [[-24, -6, -14, 4], [18, -7, 10, 3], [-6, -10, -2, 2], [26, -2, 16, 6]].forEach(([x0, y0, x1, y1]) => { g.beginPath(); g.moveTo(x + x0, y + y0); g.lineTo(x + x1, y + y1); g.strokePath(); });
    S._ckGrPozo = g;
  };
  // el arte del pozo se carga apenas se puede (es un PNG embebido)
  const cargarArte = S => {
    const A = window.CK_GRUTAS_ARTE;
    if (!A || !A.pozo || S.textures.exists('ckgr_pozo') || cargarArte.pedido) return;
    cargarArte.pedido = true;
    const im = new Image(); im.onload = () => { if (!S.textures.exists('ckgr_pozo')) { S.textures.addImage('ckgr_pozo', im); if (zona(S) === Z) pozo(S); } }; im.src = A.pozo;
  };
  const pr0 = P.preload;
  P.preload = function () { if (pr0) pr0.apply(this, arguments); try { cargarArte(this); } catch (e) {} };
  const ms0 = P.onAreaShown;
  P.onAreaShown = function () {
    const r = ms0 ? ms0.apply(this, arguments) : undefined;
    try { cargarArte(this); if (zona(this) === Z) cofresFijos(this); pozo(this); } catch (e) { console.warn('[grutas]', e); }
    return r;
  };
  const u0 = P.update;
  P.update = function () {
    const r = u0.apply(this, arguments);
    try {
      const z = zona(this);
      if (z !== Z && z !== Z1) return r;
      const pr = document.getElementById('ck-prompt'), q = !this.dialogOpen && cercaDe(this);
      const txt = q === 'sumidero' ? 'T · Bajar por el sumidero' : q === 'pozo' ? 'T · Bajar por el pozo' : '';
      if (pr && txt && (!pr.classList.contains('on') || this._ckGrCartel)) { pr.textContent = txt; pr.classList.add('on'); this._ckGrCartel = true; }
      else if (pr && !txt && this._ckGrCartel) { this._ckGrCartel = false; if (/^T · Bajar por/.test(pr.textContent)) pr.classList.remove('on'); }
    } catch (e) {}
    return r;
  };
  const mov0 = P.handlePlayerMovement;
  P.handlePlayerMovement = function () {
    const r = mov0.apply(this, arguments);
    try {
      if (zona(this) === Z && this.player && this.player.body && this.currentInterior) {
        const a = this.currentInterior.area, p = pies(this);
        const en = TELARANAS.some(([x0, y0, x1, y1]) => p.x > a.x + x0 && p.x < a.x + x1 && p.y > a.y + y0 && p.y < a.y + y1);
        if (en) {
          this.player.body.velocity.x *= 0.62; this.player.body.velocity.y *= 0.62;
          if (!this._ckGrTela) { this._ckGrTela = 1; this.createFloatingText(this.player.x, this.player.y - 46, 'Telarañas: se camina lento', 0xd6d3d1); }
        }
      }
    } catch (e) {}
    return r;
  };

  // ------------------------------------------------------------------ oscuridad, luces, trampas, cofres, bestias, mapa
  const instalar = () => {
    if (instalar.ok) return;
    if (window.CK_OSCURIDAD && !CK_OSCURIDAD.ZONAS[Z]) CK_OSCURIDAD.zona(Z, { braseros: [[1300, 330]], tinte: true, sala: PENUMBRA });
    if (window.CK_LUZ && CK_LUZ.fuente) {
      CK_LUZ.fuente((S, out) => {
        if (zona(S) !== Z || !S.currentInterior || !S.currentInterior.area) return;
        const a = S.currentInterior.area, t = (S.time && S.time.now) || 0;
        LUCES.forEach((l, i) => out.push({ x: a.x + l.x, y: a.y + l.y, c: l.c, r: l.r, f: l.f * (0.8 + 0.2 * Math.sin(t / 1100 + i * 1.3)) }));
      });
    }
    if (window.CK_ROMPIBLES && CK_ROMPIBLES.COFRES && !CK_ROMPIBLES.COFRES[Z]) CK_ROMPIBLES.COFRES[Z] = COFRES.length;
    if (window.CK_TRAMPAS_SUELO && !CK_TRAMPAS_SUELO.ZONAS[Z]) CK_TRAMPAS_SUELO.zona(Z, TRAMPAS);
    try { if (window.CK_PROF_ENTEROS && !CK_PROF_ENTEROS.test('ed_gru_x')) window.CK_PROF_ENTEROS = new RegExp(CK_PROF_ENTEROS.source.replace(')_', '|gru)_')); } catch (e) {}
    try { if (window.CK_MUSICA_MOMENTOS && CK_MUSICA_MOMENTOS.MAPA) CK_MUSICA_MOMENTOS.MAPA[ID] = 'cueva'; window.CK_SALA_ED = Object.assign(window.CK_SALA_ED || {}, { ['ed_' + ID]: 'cueva' }); } catch (e) {}
    try {
      const MM = window.CK_MINIMAPA;
      if (MM && MM.Z) {
        MM.Z[Z] = { img: ID, esc: 4, w: 1436, h: 802, ext: 0, n: 'Las Grutas', g: 'Cueva de Garra Negra' };
        if (MM.L) {
          MM.L[Z] = [{ n: 'Las Galerías (subida)', x: 1292, y: 250, ic: 'flecha', d: 'n', va: Z1 },
            { n: 'Pozo de raíces (bajada)', x: LUGAR.pozo.x, y: LUGAR.pozo.y - 20, ic: 'estrella', va: Z3 }];
          const L1 = MM.L[Z1];
          if (L1) L1.forEach(l => { if (/Sumidero/.test(l.n)) l.va = Z; });
        }
        if (MM.dibujo) MM.dibujo(ID, window.CK_GRUTAS_MINI);
      }
    } catch (e) {}
    instalar.ok = true;
  };
  document.addEventListener('DOMContentLoaded', instalar);
  if (typeof ZONE_ENEMIES !== 'undefined') {
    ZONE_ENEMIES[Z] = [['warg', 1180, 380, 40], ['warg', 860, 440, 30], ['werewolf', 560, 200, 30], ['warg', 200, 400, 30],
      ['werewolf', 800, 680, 30], ['warg', 460, 680, 30, 'night'], ['werewolf', 1000, 370, 30, 'night']]
      .filter(e => typeof ENEMY_TYPES !== 'undefined' && ENEMY_TYPES[e[0]]);
  }
})();
